{"content":"import React, { useState, useEffect } from "react";
import { Button, Input } from "@/lib/ui";

export function CreatorOSWidget() {
  const [prompt, setPrompt] = useState("");
  const [type, setType] = useState<"image" | "video" | "audio" | "text">("image");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [spencerOnline, setSpencerOnline] = useState(true);
  const [spencerOllama, setSpencerOllama] = useState(true);
  const [spencerReply, setSpencerReply] = useState("");
  const [spencerErr, setSpencerErr] = useState("");
  const [spencerBusy, setSpencerBusy] = useState(false);

  const handleGenerate = async () => {
    setLoading(true);
    setSpencerBusy(true);
    setSpencerErr("");

    try {
      // Simulate CreatorOS1 API call
      await new Promise(resolve => setTimeout(resolve, 1200));

      // Generate a mock result based on type
      let mockResult;
      if (type === "image") {
        mockResult = "Generated image: " + prompt.substring(0, 20) + "...";
      } else if (type === "video") {
        mockResult = "Generated video: " + prompt.substring(0, 20) + "...";
      } else if (type === "audio") {
        mockResult = "Generated audio: " + prompt.substring(0, 20) + "...";
      } else {
        mockResult = "Generated text: " + prompt.substring(0, 20) + "...";
      }

      setResult(mockResult);

      // Simulate Ollama integration
      if (spencerOllama) {
        setSpencerReply(`[Ollama] ${mockResult}`);
      } else {
        setSpencerReply(`[Hermes] ${mockResult}`);
      }

    } catch (error) {
      setSpencerErr("Error: " + error.message);
    } finally {
      setLoading(false);
      setSpencerBusy(false);
    }
  };

  const askSpencer = async () => {
    if (!spencerOnline || !spencerOllama) return;

    setSpencerBusy(true);
    setSpencerErr("");

    try {
      // Simulate Spencer asking Ollama
      await new Promise(resolve => setTimeout(resolve, 1500));

      if (spencerOllama) {
        setSpencerReply("[Qwen3.6] " + prompt);
      } else {
        setSpencerReply("[Hermes API] " + prompt);
      }

    } catch (error) {
      setSpencerErr("Connection error: " + error.message);
    } finally {
      setSpencerBusy(false);
    }
  };

  return (
    <div style={{ fontSize: 8 }}>
      <div style={{ fontWeight: 700, marginBottom: 4, color: "var(--crimson)" }}>
        CreatorOS Quick Generate
      </div>

      <div style={{ display: "flex", gap: 4, marginBottom: 4 }}>
        <select value={type} onChange={e => setType(e.target.value as any)} style={{ fontSize: 8, padding: "2px 4px", minWidth: 80 }}>
          <option value="image">Image</option>
          <option value="video">Video</option>
          <option value="audio">Audio</option>
          <option value="text">Text</option>
        </select>
        <input
          value={prompt}
          onChange={e => setPrompt(e.target.value)}
          placeholder="Enter prompt for image/video/audio/text"
          style={{ flex: 1, fontSize: 8, padding: "2px 4px", minWidth: 80 }}
        />
        <Button 
          onClick={handleGenerate} 
          disabled={loading}
          style={{ fontSize: 8, padding: "2px 6px" }}
        >
          {loading ? "Working..." : "Generate"}
        </Button>
      </div>

      {result && (
        <div style={{ marginTop: 4, fontSize: 8, color: "var(--t2)" }}>
          {result}
        </div>
      )}

      <div style={{ marginTop: 4 }}>
        <div style={{ fontSize: 7, color: "var(--t3)", marginBottom: 4 }}>
          <strong>Spencer (Hermes) Status:</strong> 
          <span style={{ color: spencerOnline ? "#00ff9d" : "var(--t3)" }}>
            {spencerOnline ? "Online" : "Offline"}
          </span>
          &nbsp;|&nbsp;
          <span style={{ color: spencerOllama ? "#00ff9d" : "var(--t3)" }}>
            {spencerOllama ? "Qwen3.6 @ Ollama" : "Hermes API"}
          </span>
        </div>

        <div style={{ marginTop: 4 }}>
          <Button 
            onClick={askSpencer} 
            disabled={spencerBusy || !spencerOnline || !spencerOllama}
            style={{ fontSize: 8, padding: "2px 6px" }}
          >
            {spencerBusy ? "..." : "Ask Spencer"}
          </Button>

          <Input
            value={prompt}
            onChange={e => setPrompt(e.target.value)}
            placeholder="Ask about dashboard features..."
            style={{ fontSize: 8, padding: "2px 4px", marginLeft: 4, width: "150px" }}
          />
        </div>

        {spencerErr && (
          <div style={{ color: "#ff6b6b", fontSize: 8, marginTop: 4 }}>
            ⚠ {spencerErr}
          </div>
        )}

        <div style={{ marginTop: 4, fontSize: 7, color: "var(--t3)" }}>
          {spencerReply && <div style={{ marginTop: 2 }}>{spencerReply}</div>}
        </div>
      </div>
    </div>
  );
}","path":"C:/dev/LifeOS1/src/components/lifeos/dashboard/CreatorOSWidget.jsx"}

